const rpcSpy = vi.fn().mockImplementation((funcName, params) => {
  if (funcName === 'search_content_hybrid') {
    const limit = params?.max_result || 2
    const mockResults = [
      {
        type: 'markdown',
        page_title: 'Test Guide',
        href: '/guides/test',
        content: params?.include_full_content ? 'Test content' : null,
        subsections: [
