describe('/api/graphql searchDocs', () => {
  beforeAll(() => {
    vi.spyOn(console, 'error').mockImplementation(() => {})
  })

  afterAll(() => {
    vi.restoreAllMocks()
    vi.doUnmock('~/lib/openAi')
    vi.doUnmock('~/lib/supabase')
  })

  it('should return search results when given a valid query', async () => {
