[metadata] {"type": "create", "filePath": "/workspace/repo/apps/docs/resources/globalSearch/globalSearchModel.ts", "content": "import { convertPostgrestToApiError, type ApiErrorGeneric } from '~/app/api/utils'
import { Result } from '~/features/helpers.fn'
import { openAI } from '~/lib/openAi'
import { supabase } from '~/lib/supabase'
import { GuideModel } from '../guide/guideModel'
import { type SearchResultInterface } from './globalSearchInterface'

export interface SearchDocsArgs {
  query: string
  limit?: number | null
}

export abstract class SearchResultModel {
  static async search(
    args: SearchDocsArgs,
    requestedFields: Array<string>
  ): Promise<Result<Array<SearchResultInterface>, ApiErrorGeneric>> {
    const query = args.query.trim()
    const includeFullContent = requestedFields.includes('content')

    const embeddingResult = await openAI().createContentEmbedding(query)

    return embeddingResult.flatMapAsync(async (embedding) => {
      const { data, error } = await supabase().rpc('search_content', {
        embedding,
        include_full_content: includeFullContent,
        max_result: args.limit ?? undefined,
      })

      if (error) {
        return Result.error(convertPostgrestToApiError(error))
      }

      const matches = (data ?? [])
        .map(createModelFromMatch)
        .filter((match): match is SearchResultInterface => match !== null)

      return Result.ok(matches)
    })
  }
}

interface SearchContentMatch {
  type?: string
  page_title?: string
  href?: string
  content?: string | null
  subsections?: Array<{ title?: string; href?: string; content?: string }>
}

function createModelFromMatch({
  page_title,
  href,
  content,
  subsections,
}: SearchContentMatch): SearchResultInterface | null {
  return new GuideModel({
    title: page_title,
    href,
    content: content ?? undefined,
    subsections,
  })
}
